async def act(page):
    """
    - Try the site-aware helper create_curated_collection_by_search(...) first (required when available).
    - If it returns a results list, attempt to click the first visible search-result (role='main' -> first role='article' -> first role='link')
      and return the helper's result unchanged.
    - If the helper fails, perform a manual fallback: navigate to '/', dismiss any visible overlay, locate the search input
      (prefer inside role='complementary'), enter 'Collector', trigger the search, wait for results in role='main', and click the first result.

    Notes:
    - All .nth() uses are guarded by .count() checks (handled with try/except around count()).
    - When clicking a button that belongs to a parent (e.g. inside a dialog), we use the full parent.get_by_role(...).get_by_role(...)
      form where appropriate.
    - If the KB helper returns data (an API-like response), we return it unchanged.
    """
    results = None

    # 1) Primary path: use knowledge-base helper (this helper navigates to '/' internally).
    try:
        results = await create_curated_collection_by_search(page, "Collector")
    except Exception:
        results = None

    async def click_first_result_from_main():
        """Click first article->link inside role='main'. Return True if a click was performed."""
        main = page.get_by_role("main")
        try:
            await main.wait_for(state="visible", timeout=3000)
        except Exception:
            pass

        articles = main.get_by_role("article")
        try:
            article_count = await articles.count()
        except Exception:
            article_count = 0

        if article_count > 0:
            first_article = articles.nth(0)
            links = first_article.get_by_role("link")
            try:
                link_count = await links.count()
            except Exception:
                link_count = 0

            if link_count > 0:
                # Last DOM action: click the first link inside the first article
                await links.nth(0).click()
                return True

            # Fallback: try clicking the article itself
            try:
                await first_article.click()
                return True
            except Exception:
                return False

        # Final fallback: first link directly under main
        main_links = main.get_by_role("link")
        try:
            main_link_count = await main_links.count()
        except Exception:
            main_link_count = 0

        if main_link_count > 0:
            await main_links.nth(0).click()
            return True

        return False

    # If the helper returned results, attempt to click the first visible result and return the results unchanged.
    if results is not None:
        try:
            await click_first_result_from_main()
        except Exception:
            pass
        return results

    # 2) Fallback manual flow: navigate to root, dismiss overlay, perform visible search and click first result.
    try:
        await page.goto('/')
    except Exception:
        pass

    # Try to dismiss a dialog/overlay if present using parent->child roles
    try:
        dialog_count = await page.get_by_role("dialog").count()
    except Exception:
        dialog_count = 0

    if dialog_count > 0:
        try:
            dialog = page.get_by_role("dialog").nth(0)
            closed = False
            for name in ["Close", "close", "Dismiss", "×", "x", "OK", "Got it"]:
                try:
                    cand = dialog.get_by_role("button", name=name)
                    if await cand.count() > 0:
                        await cand.nth(0).click()
                        closed = True
                        break
                except Exception:
                    continue
            if not closed:
                try:
                    all_btns = dialog.get_by_role("button")
                    if await all_btns.count() > 0:
                        await all_btns.nth(0).click()
                except Exception:
                    pass
        except Exception:
            pass
    else:
        # Try common page-level close buttons as a fallback
        for name in ["Close", "close", "Dismiss", "×", "x", "OK", "Got it"]:
            try:
                btns = page.get_by_role("button", name=name)
                if await btns.count() > 0:
                    try:
                        await btns.nth(0).click()
                        break
                    except Exception:
                        continue
            except Exception:
                continue

    # Locate search input: prefer inside complementary region
    search_input = None
    comp = None
    try:
        if await page.get_by_role("complementary").count() > 0:
            comp = page.get_by_role("complementary").nth(0)
            try:
                if await comp.get_by_role("searchbox").count() > 0:
                    search_input = comp.get_by_role("searchbox").nth(0)
                elif await comp.get_by_role("textbox").count() > 0:
                    search_input = comp.get_by_role("textbox").nth(0)
            except Exception:
                search_input = None
    except Exception:
        pass

    if search_input is None:
        try:
            if await page.get_by_role("searchbox").count() > 0:
                search_input = page.get_by_role("searchbox").nth(0)
            elif await page.get_by_role("textbox").count() > 0:
                search_input = page.get_by_role("textbox").nth(0)
        except Exception:
            search_input = None

    if search_input is None:
        # Pragmatic fallback: navigate directly to a search-results URL and click first result
        try:
            await page.goto('/?s=Collector')
        except Exception:
            pass
        try:
            await page.get_by_role("main").wait_for(state="visible", timeout=5000)
        except Exception:
            try:
                await page.wait_for_load_state('networkidle')
            except Exception:
                pass
        try:
            await click_first_result_from_main()
        except Exception:
            pass
        return []

    # Fill the search input
    try:
        await search_input.fill("Collector")
    except Exception:
        try:
            await search_input.type("Collector")
        except Exception:
            pass

    # Activate search: prefer a 'search' button inside complementary region, else press Enter
    activated = False
    try:
        if comp is not None:
            try:
                search_button = comp.get_by_role("button", name="search")
                if await search_button.count() > 0:
                    await search_button.nth(0).click()
                    activated = True
                else:
                    all_buttons = comp.get_by_role("button")
                    if await all_buttons.count() > 0:
                        await all_buttons.nth(0).click()
                        activated = True
            except Exception:
                activated = False

        if not activated:
            try:
                global_search = page.get_by_role("button", name="search")
                if await global_search.count() > 0:
                    await global_search.nth(0).click()
                    activated = True
            except Exception:
                activated = False
    except Exception:
        activated = False

    if not activated:
        try:
            await search_input.press("Enter")
        except Exception:
            pass

    # Wait for results and click the first one
    try:
        await page.get_by_role("main").wait_for(state="visible", timeout=5000)
    except Exception:
        try:
            await page.wait_for_load_state('networkidle')
        except Exception:
            pass

    try:
        await click_first_result_from_main()
    except Exception:
        pass

    return []

